// Self-created, CC0 test font: one triangle glyph mapped only to U+0041 (A).
// The remaining sample characters intentionally exercise browser fallback.
// A minimal sfnt with OS/2, cmap, glyf, head, hhea, hmtx, loca, maxp, name, post;
// no customer font, external asset, parser dependency, or shaping claim.
const TRIANGLE_TTF = "";

export const FONT_SPECIMEN_SHA256 = "186b95ec3a4c27409437e166f668ed46445a1f557c2a9334772bf4e79c7268c5";
export const FONT_SPECIMEN_PATH = "fonts/A's [specimen].ttf";

export function fontSpecimenBytes(): Uint8Array {
  return Uint8Array.from(atob(TRIANGLE_TTF), (char) => char.charCodeAt(0));
}
